import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

##SOLUTION##

func main() {
	reader := bufio.NewReader(os.Stdin)
	var sb strings.Builder
	buf := make([]byte, 4096)
	for {
		n, err := reader.Read(buf)
		if n > 0 {
			sb.Write(buf[:n])
		}
		if err != nil {
			break
		}
	}
	tokens := strings.Fields(sb.String())
	i := 0
	n, _ := strconv.Atoi(tokens[i]); i++
	tree := make([]int, n); for j := 0; j < n; j++ { tree[j], _ = strconv.Atoi(tokens[i]); i++ }
	ans := maxDepth(tree)
	fmt.Println(ans)
}

